1	package retention
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12		"sync"
13		"syscall"
14	)
15	
16	// 状态文件与锁文件的固定名称，位于调用者选择的本地目录内。
17	const (
18		stateFileName = "retention-state.json"
19		lockFileName  = ".retention.lock"
20	)
21	
22	// Store 是一个本地保管库，对应调用者选择的一个本地保存位置。
23	//
24	// 同一个目录可以被本机上的多个程序（进程）同时打开：
25	// 每次办理都会取得跨进程的排他文件锁，并从磁盘重新读取状态，
26	// 因此两个程序对同一档案的冻结、销毁一定有明确的先后顺序。
27	type Store struct {
28		dir string
29	
30		// opMu 串行化当前 Store 实例内的办理；跨进程互斥由文件锁保证。
31		opMu sync.RWMutex
32	}
33	
34	// Open 打开（或创建）一个本地保存位置。
35	// 目录不存在时会创建；状态文件不存在时按空库打开，可以正常登记。
36	// 状态文件已存在但内容损坏（空文件、只有空白、内容为 null、合法对象后面
37	// 还拼接了其他内容等），或其中保存的记录不满足业务不变量（例如已解除冻结
38	// 缺少解除原因或解除日期、解除日期早于冻结日期、已销毁档案与已关闭清册
39	// 对应不上）时返回 ErrCorruptState，
40	// 不会返回可继续办理的保管库，已有记录保持原样，不会被清空、修补或覆盖。
41	func Open(dir string) (*Store, error) {
42		if dir == "" {
43			return nil, errors.New("retention: 保存位置不能为空")
44		}
45		if err := os.MkdirAll(dir, 0o755); err != nil {
46			return nil, fmt.Errorf("retention: 无法创建保存位置: %w", err)
47		}
48		s := &Store{dir: dir}
49		// 提前读一次，让损坏的状态文件在打开时就暴露，而不是等到第一次办理。
50		if _, err := s.load(); err != nil {
51			return nil, err
52		}
53		return s, nil
54	}
55	
56	// Close 释放保管库。当前实现没有跨操作持有的资源，保留它以稳定公开入口形态。
57	func (s *Store) Close() error { return nil }
58	
59	func (s *Store) statePath() string { return filepath.Join(s.dir, stateFileName) }
60	func (s *Store) lockPath() string  { return filepath.Join(s.dir, lockFileName) }
61	
62	// lock 取得跨进程排他锁，返回解锁函数。
63	// 每次办理各自加锁、解锁，这样同一位置也允许同进程或跨进程的多个 Store 并存。
64	func (s *Store) lock() (func(), error) {
65		f, err := os.OpenFile(s.lockPath(), os.O_CREATE|os.O_RDWR, 0o600)
66		if err != nil {
67			return nil, fmt.Errorf("retention: 无法打开锁文件: %w", err)
68		}
69		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX); err != nil {
70			f.Close()
71			return nil, fmt.Errorf("retention: 无法取得保存位置锁: %w", err)
72		}
73		return func() {
74			_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
75			_ = f.Close()
76		}, nil
77	}
78	
79	// rlock 取得跨进程共享锁，用于只读核对。
80	func (s *Store) rlock() (func(), error) {
81		f, err := os.OpenFile(s.lockPath(), os.O_CREATE|os.O_RDWR, 0o600)
82		if err != nil {
83			return nil, fmt.Errorf("retention: 无法打开锁文件: %w", err)
84		}
85		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_SH); err != nil {
86			f.Close()
87			return nil, fmt.Errorf("retention: 无法取得保存位置锁: %w", err)
88		}
89		return func() {
90			_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
91			_ = f.Close()
92		}, nil
93	}
94	
95	// load 从磁盘读取最新状态。文件不存在时返回一份空状态（尚未建立记录）。
96	//
97	// 文件已经存在时，必须完整包含且只包含一个 JSON 对象（前后允许空白）：
98	// 零字节或只有空白的文件、内容为 null 的文件、合法对象后面还拼接了
99	// 第二个 JSON 值或无法解析的文字，都判为损坏并返回 ErrCorruptState，
100	// 绝不只使用前一段内容，也不会改动原文件。
101	//
102	// JSON 能解析不代表记录合法：任何已解除冻结都必须同时带有非空白的
103	// 解除原因和有效的解除日期，且解除日期不早于冻结日期——与解除功能
104	// 办理时的要求一致。缺少任一信息或日期顺序不成立时，整份保管库同样
105	// 判为损坏并返回 ErrCorruptState，错误信息指明涉及的档案与冻结编号。
106	//
107	// 已销毁档案与已关闭清册也必须相互对应：每份已销毁档案记下的申请编号
108	// 必须能找到一份清册，且该清册恰好收录该档案一次；清册收录的每份档案
109	// 也必须存在、标成已销毁并指回这份清册。已销毁档案找不到清册、同一档案
110	// 出现在多份清册、归属指向别的申请，或未销毁档案仍挂有清册申请编号，
111	// 都说明记录已无法说明档案由哪次申请销毁，整份保管库判为损坏并返回
112	// ErrCorruptState，错误信息指明涉及的档案编号与相关申请编号。
113	func (s *Store) load() (*storeData, error) {
114		raw, err := os.ReadFile(s.statePath())
115		if err != nil {
116			if errors.Is(err, os.ErrNotExist) {
117				return newStoreData(), nil
118			}
119			return nil, fmt.Errorf("retention: 无法读取状态文件: %w", err)
120		}
121		trimmed := bytes.TrimSpace(raw)
122		if len(trimmed) == 0 {
123			return nil, fmt.Errorf("retention: 状态文件为空或只有空白: %w", ErrCorruptState)
124		}
125		// json.Unmarshal 对 null 不报错且保持目标不变，必须单独拒绝。
126		if string(trimmed) == "null" {
127			return nil, fmt.Errorf("retention: 状态文件内容为 null，不是有效的保管库记录: %w", ErrCorruptState)
128		}
129		data := newStoreData()
130		// json.Unmarshal 要求整个输入恰好是一个 JSON 值：
131		// 合法对象后面再拼接任何内容都会在这里报错。
132		if err := json.Unmarshal(raw, data); err != nil {
133			return nil, fmt.Errorf("retention: 状态文件内容无法解析: %v: %w", err, ErrCorruptState)
134		}
135		if data.Archives == nil {
136			data.Archives = map[string]*archiveRecord{}
137		}
138		if data.Manifests == nil {
139			data.Manifests = map[string]*manifestRecord{}
140		}
141		// 语义校验先于任何兼容处理：已解除冻结必须与既有解除功能遵守同一要求——
142		// 解除原因与解除日期齐备，且解除日期不早于冻结日期。
143		// 只有“已解除”标记而缺少任一信息，或解除日期早于冻结日期的记录
144		// 一律判为损坏（即使所属档案已销毁）；绝不据此继续办理或修补记录。
145		if err := validateFreezeReleaseRecords(data); err != nil {
146			return nil, err
147		}
148		// 已销毁档案与已关闭清册必须相互对应，否则无法说明档案由哪次申请销毁。
149		// 关系损坏时绝不挑选其中一份记录继续使用，也不补清册或改销毁标记。
150		if err := validateManifestConsistency(data); err != nil {
151			return nil, err
152		}
153		// 兼容引入修订功能之前保存的保管库：没有记录最初截止日时，
154		// 登记截止日就是最初截止日。
155		for _, ar := range data.Archives {
156			if ar.InitialEnd.IsZero() {
157				ar.InitialEnd = ar.End
158			}
159		}
160		return data, nil
161	}
162	
163	// validateFreezeReleaseRecords 检查库内全部已解除冻结记录是否完整合法。
164	//
165	// 正常解除保存的记录必然同时带有非空白的解除原因和有效的解除日期，
166	// 且解除日期不早于冻结日期。缺少解除原因、解除日期缺失或为 null、
167	// 解除日期早于冻结日期，都说明保存内容已损坏，返回可由 ErrCorruptState
168	// 识别的错误，并在信息中给出涉及的档案编号与冻结编号，便于定位记录。
169	// 校验覆盖整个保管库的全部已解除冻结，与本次办理名单无关：
170	// 即使异常记录所属档案已经销毁，也不能把不完整的解除信息当作正常历史。
171	// 未解除冻结没有解除日期和原因是合法状态，不在此报错。
172	func validateFreezeReleaseRecords(data *storeData) error {
173		// map 遍历顺序不稳定，按档案编号排序后再检查，保证错误信息稳定。
174		archiveIDs := make([]string, 0, len(data.Archives))
175		for id := range data.Archives {
176			archiveIDs = append(archiveIDs, id)
177		}
178		sort.Strings(archiveIDs)
179		for _, id := range archiveIDs {
180			ar := data.Archives[id]
181			if ar == nil {
182				return fmt.Errorf("retention: 档案 %s 的登记记录缺失，状态文件已损坏: %w",
183					id, ErrCorruptState)
184			}
185			for _, fr := range ar.Freezes {
186				if fr == nil {
187					return fmt.Errorf("retention: 档案 %s 下存在缺失的冻结记录，状态文件已损坏: %w",
188						id, ErrCorruptState)
189				}
190				if !fr.Released {
191					// 未解除冻结没有解除日期与原因是合法状态。
192					continue
193				}
194				switch {
195				case strings.TrimSpace(fr.ReleaseReason) == "":
196					return fmt.Errorf(
197						"retention: 档案 %s 的冻结 %s 标记为已解除但缺少解除原因，记录已损坏: %w",
198						id, fr.ID, ErrCorruptState)
199				case fr.ReleasedOn == nil:
200					return fmt.Errorf(
201						"retention: 档案 %s 的冻结 %s 标记为已解除但缺少解除日期，记录已损坏: %w",
202						id, fr.ID, ErrCorruptState)
203				case fr.ReleasedOn.IsZero():
204					return fmt.Errorf(
205						"retention: 档案 %s 的冻结 %s 的解除日期无效，记录已损坏: %w",
206						id, fr.ID, ErrCorruptState)
207				case fr.ReleasedOn.Before(fr.FrozenOn):
208					return fmt.Errorf(
209						"retention: 档案 %s 的冻结 %s 的解除日期 %s 早于冻结日期 %s，记录已损坏: %w",
210						id, fr.ID, fr.ReleasedOn, fr.FrozenOn, ErrCorruptState)
211				}
212			}
213		}
214		return nil
215	}
216	
217	// validateManifestConsistency 检查已销毁档案与已关闭清册之间的对应关系。
218	//
219	// 正常销毁保存的记录必然满足双向对应：每份已销毁档案记下的申请编号
220	// 能找到一份清册，且该清册恰好收录该档案一次；清册收录的每份档案都
221	// 存在、标成已销毁，并指回这份清册。已销毁档案没有清册归属、归属的
222	// 清册不存在或未收录该档案、同一档案出现在多份清册、清册重复收录同一
223	// 档案、清册收录了不存在或未销毁的档案、档案归属指向别的申请，以及
224	// 未销毁档案仍挂有清册申请编号，都说明保存内容已损坏，返回可由
225	// ErrCorruptState 识别的错误，并在信息中给出涉及的档案编号与相关
226	// 申请编号，便于定位记录。校验覆盖整个保管库，与本次办理名单无关；
227	// 未销毁且没有清册归属的档案是合法记录，不在此报错。
228	func validateManifestConsistency(data *storeData) error {
229		// map 遍历顺序不稳定，按编号排序后再检查，保证错误信息稳定。
230		archiveIDs := make([]string, 0, len(data.Archives))
231		for id := range data.Archives {
232			archiveIDs = append(archiveIDs, id)
233		}
234		sort.Strings(archiveIDs)
235		for _, id := range archiveIDs {
236			ar := data.Archives[id]
237			if ar == nil {
238				// 缺失的登记记录已由 validateFreezeReleaseRecords 报告。
239				continue
240			}
241			if !ar.Destroyed {
242				if ar.ManifestID != "" {
243					return fmt.Errorf(
244						"retention: 档案 %s 未销毁却挂有清册申请编号 %s，记录已损坏: %w",
245						id, ar.ManifestID, ErrCorruptState)
246				}
247				continue
248			}
249			if ar.ManifestID == "" {
250				return fmt.Errorf(
251					"retention: 档案 %s 已销毁但没有记录所属清册的申请编号，记录已损坏: %w",
252					id, ErrCorruptState)
253			}
254			rec, ok := data.Manifests[ar.ManifestID]
255			if !ok || rec == nil {
256				return fmt.Errorf(
257					"retention: 档案 %s 已销毁，但其所属清册 %s 不存在，记录已损坏: %w",
258					id, ar.ManifestID, ErrCorruptState)
259			}
260			count := 0
261			for _, e := range rec.Entries {
262				if e.ID == id {
263					count++
264				}
265			}
266			if count != 1 {
267				return fmt.Errorf(
268					"retention: 档案 %s 在其所属清册 %s 中收录 %d 次（应恰好一次），记录已损坏: %w",
269					id, ar.ManifestID, count, ErrCorruptState)
270			}
271		}
272	
273		applicationIDs := make([]string, 0, len(data.Manifests))
274		for id := range data.Manifests {
275			applicationIDs = append(applicationIDs, id)
276		}
277		sort.Strings(applicationIDs)
278		for _, appID := range applicationIDs {
279			rec := data.Manifests[appID]
280			if rec == nil {
281				return fmt.Errorf(
282					"retention: 清册 %s 的内容缺失，记录已损坏: %w",
283					appID, ErrCorruptState)
284			}
285			seen := make(map[string]int, len(rec.Entries))
286			for _, e := range rec.Entries {
287				seen[e.ID]++
288				ar, ok := data.Archives[e.ID]
289				if !ok || ar == nil {
290					return fmt.Errorf(
291						"retention: 清册 %s 收录的档案 %s 不存在，记录已损坏: %w",
292						appID, e.ID, ErrCorruptState)
293				}
294				if !ar.Destroyed {
295					return fmt.Errorf(
296						"retention: 清册 %s 收录的档案 %s 未标记为已销毁，记录已损坏: %w",
297						appID, e.ID, ErrCorruptState)
298				}
299				if ar.ManifestID != appID {
300					return fmt.Errorf(
301						"retention: 清册 %s 收录的档案 %s 归属另一申请 %s，记录已损坏: %w",
302						appID, e.ID, ar.ManifestID, ErrCorruptState)
303				}
304			}
305			// 同一档案被同一份清册重复收录（档案侧的恰好一次检查只覆盖
306			// 归属指向该清册的情况，这里对全部收录记录再核对一遍）。
307			entryIDs := make([]string, 0, len(seen))
308			for id := range seen {
309				entryIDs = append(entryIDs, id)
310			}
311			sort.Strings(entryIDs)
312			for _, id := range entryIDs {
313				if seen[id] > 1 {
314					return fmt.Errorf(
315						"retention: 清册 %s 重复收录档案 %s（共 %d 次），记录已损坏: %w",
316						appID, id, seen[id], ErrCorruptState)
317				}
318			}
319		}
320		return nil
321	}
322	
323	// save 原子地写入状态：先写同目录临时文件并刷盘，再 rename 替换，最后刷目录。
324	// 写入过程中崩溃不会留下半截状态，旧文件保持完好。
325	func (s *Store) save(data *storeData) error {
326		buf, err := json.MarshalIndent(data, "", "  ")
327		if err != nil {
328			return fmt.Errorf("retention: 状态编码失败: %w", err)
329		}
330		tmp, err := os.CreateTemp(s.dir, ".retention-state-*.tmp")
331		if err != nil {
332			return fmt.Errorf("retention: 无法创建临时状态文件: %w", err)
333		}
334		tmpName := tmp.Name()
335		cleanup := func() { _ = os.Remove(tmpName) }
336		if _, err := tmp.Write(buf); err != nil {
337			tmp.Close()
338			cleanup()
339			return fmt.Errorf("retention: 写入状态失败: %w", err)
340		}
341		if err := tmp.Sync(); err != nil {
342			tmp.Close()
343			cleanup()
344			return fmt.Errorf("retention: 刷盘状态失败: %w", err)
345		}
346		if err := tmp.Close(); err != nil {
347			cleanup()
348			return fmt.Errorf("retention: 关闭状态文件失败: %w", err)
349		}
350		if err := os.Rename(tmpName, s.statePath()); err != nil {
351			cleanup()
352			return fmt.Errorf("retention: 替换状态文件失败: %w", err)
353		}
354		// 刷目录，确保 rename 在崩溃后仍然落盘。
355		if dir, err := os.Open(s.dir); err == nil {
356			_ = dir.Sync()
357			_ = dir.Close()
358		}
359		return nil
360	}
361	
362	// mutate 在跨进程排他锁内重读状态、办理变更，仅在全部校验通过后写回。
363	// fn 返回错误时绝不写盘，磁盘上的已有记录不受影响。
364	func (s *Store) mutate(fn func(*storeData) error) error {
365		s.opMu.Lock()
366		defer s.opMu.Unlock()
367		unlock, err := s.lock()
368		if err != nil {
369			return err
370		}
371		defer unlock()
372		data, err := s.load()
373		if err != nil {
374			return err
375		}
376		if err := fn(data); err != nil {
377			return err
378		}
379		return s.save(data)
380	}
381	
382	// view 在共享锁内重读状态并执行只读查询。
383	func (s *Store) view(fn func(*storeData) error) error {
384		s.opMu.RLock()
385		defer s.opMu.RUnlock()
386		unlock, err := s.rlock()
387		if err != nil {
388			return err
389		}
390		defer unlock()
391		data, err := s.load()
392		if err != nil {
393			return err
394		}
395		return fn(data)
396	}
397

