321			Reason: "诉讼", FrozenOn: MustParseDate("2024-06-01"),
322		}); err != nil {
323			t.Fatalf("冻结失败: %v", err)
324		}
325	
326		// 冻结档案允许缩短期限，但修订不解除冻结。
327		revise(t, s, "R-1", "A-001", "2025-01-10", "2024-06-02", "2024-06-01", "缩短")
328		h, _, _ := s.History("A-001")
