331		}
332	
333		// 期限已缩短到到期，但冻结仍阻止销毁。
334		_, err := s.Destroy(DestructionRequest{
335			ApplicationID: "APP-1",
336			ProcessedOn:   MustParseDate("2024-06-02"),
337			ArchiveIDs:    []string{"A-001"},
338		})
