411		s2, err := Open(dir)
412		if err != nil {
413			t.Fatalf("打开第二个保管库失败: %v", err)
414		}
415		defer s2.Close()
416		reg(t, s1, "A-001", "合同", "2020-01-01", "2025-01-10")
417	
418		// 两个程序同时把同一截止日改成不同日期：只能成功一次。
419		var wg sync.WaitGroup
420		errs := make([]error, 2)
421		for i, newEnd := range []string{"2026-01-10", "2027-01-10"} {
422			wg.Add(1)
423			go func(i int, newEnd string) {
424				defer wg.Done()
425				s := []*Store{s1, s2}[i]
426				_, errs[i] = s.Revise(ReviseInput{
427					RevisionID:  "R-" + newEnd,
428					ArchiveID:   "A-001",
429					OriginalEnd: MustParseDate("2025-01-10"),
430					NewEnd:      MustParseDate(newEnd),
431					RevisedOn:   MustParseDate("2024-12-01"),
432					Reason:      "并发修订",
433				})
434			}(i, newEnd)
435		}
436		wg.Wait()
