package retention

import (
	"errors"
	"strings"
	"testing"
)

// 最初截止日、按成功顺序保存的修订链与当前截止日必须连续对应。
// 下列记录 JSON 都能解析，但期限关系自相矛盾，Open 必须按损坏处理，
// 返回 ErrCorruptState；错误指出档案编号，能定位到修订时同时指出修订编号，
// 且原文件保持原样。
func TestOpenRejectsBrokenRevisionChains(t *testing.T) {
	base := `{"version":1,"archives":{"A-1":{"id":"A-1","category":"合同","start":"2020-01-01","end":"%s","initial_end":"%s","destroyed":false,"freezes":[],"revisions":%s}},"manifests":{}}`
	rev := func(id, oldEnd, newEnd, on string) string {
		return `{"id":"` + id + `","old_end":"` + oldEnd + `","new_end":"` + newEnd +
			`","revised_on":"` + on + `","reason":"r"}`
	}
	r1 := rev("R-1", "2025-01-10", "2026-01-10", "2025-01-09")
	r2 := rev("R-2", "2026-01-10", "2027-01-10", "2025-02-01")

	cases := map[string]struct {
		end, initial string
		revisions    string
		wantRevision string
	}{
		// 任务场景：修订已把期限延长到 2026-01-10，当前截止日却仍是 2025-01-10。
		"当前截止日与末次修订不符": {
			end: "2025-01-10", initial: "2025-01-10",
			revisions:    "[" + r1 + "]",
			wantRevision: "R-1",
		},
		"第一条修订原截止日不等于最初截止日": {
			end: "2026-01-10", initial: "2025-01-10",
			revisions:    "[" + rev("R-1", "2025-06-30", "2026-01-10", "2025-01-09") + "]",
			wantRevision: "R-1",
		},
		"后续修订原截止日接不上上一条新截止日": {
			end: "2027-01-10", initial: "2025-01-10",
			revisions:    "[" + r1 + "," + rev("R-2", "2026-06-30", "2027-01-10", "2025-02-01") + "]",
			wantRevision: "R-2",
		},
		"修订链完整但末次新截止日对不上当前值": {
			end: "2026-06-30", initial: "2025-01-10",
			revisions:    "[" + r1 + "," + r2 + "]",
			wantRevision: "R-2",
		},
		"修订列表中存在空记录": {
			end: "2026-01-10", initial: "2025-01-10",
			revisions:    "[null]",
			wantRevision: "",
		},
		"空记录混在合法修订之间": {
			end: "2027-01-10", initial: "2025-01-10",
			revisions:    "[" + r1 + ",null]",
			wantRevision: "",
		},
		"已有修订却缺少最初截止日": {
			end: "2026-01-10", initial: "",
			revisions:    "[" + r1 + "]",
			wantRevision: "",
		},
		"无修订但最初截止日与当前截止日不符": {
			end: "2025-01-10", initial: "2024-01-01",
			revisions:    "[]",
			wantRevision: "",
		},
	}
	for name, tc := range cases {
		t.Run(name, func(t *testing.T) {
			content := tc.content(t, base, tc.end, tc.initial, tc.revisions)
			dir := t.TempDir()
			writeStateFile(t, dir, content)

			s, err := Open(dir)
			if err == nil {
				s.Close()
				t.Fatal("自相矛盾的期限记录不应打开成功")
			}
			if !errors.Is(err, ErrCorruptState) {
				t.Fatalf("错误应可判定为 ErrCorruptState，得到 %v", err)
			}
			msg := err.Error()
			if !strings.Contains(msg, "A-1") {
				t.Fatalf("错误信息应指出档案编号 A-1，得到 %v", err)
			}
			if tc.wantRevision != "" && !strings.Contains(msg, tc.wantRevision) {
				t.Fatalf("错误信息应指出修订编号 %s，得到 %v", tc.wantRevision, err)
			}
			if got := readStateFile(t, dir); got != content {
				t.Fatalf("打开失败后原文件被改动: %q -> %q", content, got)
			}
		})
	}
}

// content 拼装测试状态；缺少最初截止日时直接省略 initial_end 字段。
func (tc struct {
	end, initial, revisions, wantRevision string
}) content(t *testing.T, base, end, initial, revisions string) string {
	t.Helper()
	if initial == "" {
		return strings.NewReplacer(
			`,"initial_end":"%s"`, "",
			`%s`, end,
		).Replace(`{"version":1,"archives":{"A-1":{"id":"A-1","category":"合同","start":"2020-01-01","end":"` +
			end + `","destroyed":false,"freezes":[],"revisions":` + revisions + `}},"manifests":{}}`)
	}
	return sprintf(base, end, initial, revisions)
}

func sprintf(format string, args ...any) string {
	return stringsTrim(format, args)
}

// stringsTrim 仅用于让上面的 content 辅助保持简洁。
func stringsTrim(format string, args []any) string {
	return fmtSprintf(format, args...)
}

