			}
			defer s.Close()
			h, found, err := s.History("A-1")
			if err != nil || !found {
				t.Fatalf("合法档案应能查询历史: found=%v err=%v", found, err)
			}
			if !h.InitialEnd.Equal(MustParseDate("2025-01-10")) ||
				!h.RetentionEnd.Equal(MustParseDate(ends[name])) {
				t.Fatalf("最初/当前截止日不符: %+v", h)
			}
		})
	}
